def normalize_recipe(raw):
    if not isinstance(raw,dict):raise ValueError('Recipe must be an object')
    r=copy.deepcopy(raw)
    if not re.fullmatch(r'[a-z0-9_]+(?:\.[a-z0-9_]+)*',str(r.get('id',''))):raise ValueError('Invalid stable id')
    if not re.fullmatch(r'[a-z0-9_]+',str(r.get('family',''))):raise ValueError('Invalid family/path')
    if r.get('archetype') not in SUPPORTED:raise ValueError('Unsupported archetype')
    r.setdefault('design',r['id'].split('.')[-1])
    if r['archetype']!='layered' and DESIGNS.get(r['design'])!=r['archetype']:raise ValueError('Unsupported design/archetype combination; author a new shape grammar')
    r.setdefault('materials',[ALIASES.get(r.get('material'),r.get('material'))])
    if not isinstance(r['materials'],list) or not r['materials'] or any(m not in MATERIALS for m in r['materials']):raise ValueError('Unknown material')
    if not isinstance(r.get('parts'),list) or not r['parts']:raise ValueError('Recipe needs physical parts')
    for p in r['parts']:
        if not isinstance(p,dict) or not p.get('name') or p.get('material') not in MATERIALS or not p.get('construction'):raise ValueError('Invalid part material/construction')
    for key,value in [('view','inventory_icon'),('state','intact'),('camera','inventory_3q'),('size',[64,64])]:
        r.setdefault(key,value)
        if r[key]!=value:raise ValueError('Unsupported '+key+'; requires separately authored representation')
    if r.get('required_views',['inventory_icon'])!=['inventory_icon'] or r.get('required_states',['intact'])!=['intact']:raise ValueError('Missing required representation/state')
    r.setdefault('render_mode','procedural')
    if r['render_mode'] not in ['procedural','authored_template']:raise ValueError('Unknown render mode')
    if r['render_mode']=='authored_template':
        if r['design'] not in AUTHORED_TEMPLATES:raise ValueError('No original authored native template; provide geometry layers')
        r['template_sha256']=AUTHORED_TEMPLATE_HASHES[r['design']]
        if r.get('material_overrides'):raise ValueError('Use procedural/layered mode for material-role edits; authored pixels cannot be honestly relit by a material name')
    r.setdefault('seed',20261106)
    if type(r['seed']) is not int or r['seed']<0:raise ValueError('seed must be nonnegative integer')
    r.setdefault('recipe_version',RECIPE_VERSION)
    if not isinstance(r['recipe_version'],str) or not r['recipe_version']:raise ValueError('recipe_version required')
    r.setdefault('light',[-0.55,-0.75,0.7])
    if r['light']!=[-0.55,-0.75,0.7]:raise ValueError('Unsupported lighting; locked upper-left calibration')
    if r['archetype']=='layered':
        if not r.get('originality_provenance'):raise ValueError('Authored layers require originality provenance')
        if not isinstance(r.get('layers'),list) or not 1<=len(r['layers'])<=128:raise ValueError('Need 1–128 original construction layers')
        for layer in r['layers']:
            if layer.get('op') not in ['polygon','ellipse','line']:raise ValueError('Unsupported authored layer operation')
            if layer['op']=='ellipse':
                box=layer.get('box')
                if not isinstance(box,list) or len(box)!=4 or any(type(v) is not int for v in box) or box[0]>=box[2] or box[1]>=box[3]:raise ValueError('Invalid authored ellipse box')
            else:
                points=layer.get('points')
                minimum=3 if layer['op']=='polygon' else 2
                if not isinstance(points,list) or len(points)<minimum or any(not isinstance(pt,(list,tuple)) or len(pt)!=2 for pt in points):raise ValueError('Invalid authored polygon/line topology')
            if type(layer.get('width',1)) is not int or not 1<=layer.get('width',1)<=8:raise ValueError('Invalid native line width')
            if layer.get('material') not in MATERIALS or type(layer.get('tone')) is not int or not 0<=layer['tone']<=5:raise ValueError('Invalid layer material/tone')
            points=layer.get('points') if layer['op']!='ellipse' else layer.get('box')
            flat=[v for point in points for v in point] if layer['op']!='ellipse' and isinstance(points,list) else points
            if not isinstance(flat,list) or not flat or any(type(v) is not int or not 0<=v<64 for v in flat):raise ValueError('Layers require original native64 pixel coordinates')
    for source,target in r.get('material_overrides',{}).items():
        if source not in MATERIALS or target not in MATERIALS:raise ValueError('Invalid material-role override')
    json.dumps(r,allow_nan=False)
    r.setdefault('wear','used')
    if r['wear'] not in ['clean','used','worn']:raise ValueError('Unknown wear state')
    return r

class PixelSurface:
    """Painter-ordered original component masks shaded on the final 64px grid."""
    def __init__(self,seed=0):
        self.image=Image.new('RGBA',(64,64));self.d=ImageDraw.Draw(self.image);self.seed=seed;self.overrides={}
    def shape(self,points,mat='bare_steel',tone=3,form='plane',tint=None,texture=False):
        mask=Image.new('L',(64,64));md=ImageDraw.Draw(mask)
        md.polygon(points,fill=255)
        self.mask(mask,mat,tone,form,tint,texture)
    def ellipse(self,box,mat='bare_steel',tone=3,form='round',tint=None,texture=False):
        mask=Image.new('L',(64,64));ImageDraw.Draw(mask).ellipse(box,fill=255)
        self.mask(mask,mat,tone,form,tint,texture)
    def mask(self,mask,mat,tone,form,tint,texture):
        bbox=mask.getbbox()
        if not bbox:return
        mat=self.overrides.get(mat,mat)
        pal=MATERIALS[mat]
        if tint:
            # Local colorway affects hue, not material-specific light response.
            reference=max(1,sum(pal[3])/3)
            pal=tuple(tuple(max(0,min(255,round(t*(sum(p)/3)/reference))) for t in tint) for p in pal)
        pix=self.image.load();alpha=mask.load();x0,y0,x1,y1=bbox;w=max(1,x1-x0);h=max(1,y1-y0)
        for y in range(y0,y1):
            for x in range(x0,x1):
                if not alpha[x,y]:continue
                u=(x-x0)/w;v=(y-y0)/h
                level=float(tone)
                if form=='plane':level+=.34-.5*u-.25*v
                if texture and mat in ('paper','fabric','organic','wood','leather'):
                    cluster=((x//2)*19+(y//2)*37+self.seed)%53
                    if cluster in (1,2):level-=.55
                if form in ['round','cylinder']:
                    # Quantized cylindrical/spherical normals, left key and right falloff.
                    level+=1.28*math.cos((u-.23)*math.pi*1.45)-0.7*u-0.55*v
                    if form=='round':level+=0.6*math.cos(v*math.pi)-0.2
                    if mat in ['fabric','leather','paper']:level=min(level,4.2)
                if form=='fold':
                    level+=0.32*math.sin((u*2.0+v*.5)*math.pi)-.25*v
                if texture:
                    if mat=='wood':level+=(-.65 if (x//2+y//6+self.seed%7)%9==0 else 0)
                    elif mat=='fabric':level+=(-.3 if (x//2+y//3)%7==0 else 0)
                    elif mat=='organic':level+=(-.4 if (x//3+2*(y//3)+self.seed%5)%11==0 else 0)
                    elif mat=='leather':level+=(-.25 if (x//3+y//5)%9==0 else 0)
                if mat in ['bare_steel','aluminum','glass'] and form!='plane':
                    if .15<u<.23:level+=1.2
                    if u>.78:level-=.35
                pix[x,y]=pal[max(0,min(5,int(round(level))))]+(255,)
    def line(self,points,mat='bare_steel',tone=3,width=1):self.d.line(points,fill=MATERIALS[mat][tone]+(255,),width=width)
    def dot(self,x,y,mat='bare_steel',tone=4):self.d.point((x,y),fill=MATERIALS[mat][tone]+(255,))
    def rivet(self,x,y):
        self.dot(x,y,'bare_steel',1);self.dot(x,y-1,'bare_steel',5);self.dot(x+1,y,'bare_steel',3)
    def seam(self,points,mat='fabric',tone=4):
        self.line(points,mat,max(0,tone-3));
        a,b=points[0],points[-1];n=max(abs(b[0]-a[0]),abs(b[1]-a[1]))
        for i in range(1,n,3):self.dot(round(a[0]+(b[0]-a[0])*i/max(1,n)),round(a[1]+(b[1]-a[1])*i/max(1,n)),mat,tone)
    def prism(self,top,depth=6,mat='bare_steel',tint=None):
        a,b,c,d=top
        self.shape([a,d,(d[0],d[1]+depth),(a[0],a[1]+depth)],mat,2,tint=tint)
        self.shape([d,c,(c[0],c[1]+depth),(d[0],d[1]+depth)],mat,1,tint=tint)
        self.shape(top,mat,4,tint=tint)
        self.line([a,b,c],mat,5)

