@lru_cache(maxsize=32)
def _base_image(encoded):
    r=json.loads(encoded);s=PixelSurface(r['seed']);s.overrides=r.get('material_overrides',{})
    if r.get('render_mode')=='authored_template':
        data=base64.b64decode(AUTHORED_TEMPLATES[r['design']])
        if hashlib.sha256(data).hexdigest()!=r['template_sha256']:raise ValueError('Embedded original template integrity failure')
        with Image.open(io.BytesIO(data)) as template:
            if template.mode!='RGBA' or template.size!=(64,64):raise ValueError('Original template must be native64 RGBA')
            s.image=template.copy()
    elif r['archetype']=='layered':
        for layer in r['layers']:
            mat=layer['material'];tone=layer['tone'];op=layer['op']
            if op=='polygon':s.shape(layer['points'],mat,tone,layer.get('form','plane'),texture=layer.get('texture',False))
            elif op=='ellipse':s.ellipse(layer['box'],mat,tone,layer.get('form','round'),texture=layer.get('texture',False))
            else:s.line(layer['points'],mat,tone,layer.get('width',1))
    else:draw_design(s,r)
    # Remove any accidental RGB under transparency; no antialias/downsampling.
    return s.image

def render_icon(recipe,variant=0):
    r=normalize_recipe(recipe)
    if type(variant) is not int or variant<0:raise ValueError('variant must be nonnegative integer')
    im=_base_image(json.dumps(r,sort_keys=True,separators=(',',':'))).copy()
    if variant and r['wear']!='clean':
        rng=random.Random(hashlib.sha256((r['id']+str(r['seed'])+':'+str(variant)).encode()).digest())
        # Only a few attached, material-appropriate scuff pixels. Never new objects.
        pts=[(x,y) for y in range(8,56) for x in range(8,56) if im.getpixel((x,y))[3] and im.getpixel((x-1,y))[3] and im.getpixel((x+1,y))[3]]
        if pts:
            x,y=pts[rng.randrange(len(pts))];c=im.getpixel((x,y));delta=-12 if variant%2 else 10
            ImageDraw.Draw(im).line((x,y,x+1,y),fill=tuple(max(0,min(255,v+delta)) for v in c[:3])+(255,))
    return im

def material_demo(path):
    board=Image.new('RGB',(7*100,2*120),(29,36,39));d=ImageDraw.Draw(board)
    for i,mat in enumerate(MATERIALS):
        s=PixelSurface();s.prism([(8,33),(35,14),(54,23),(26,43)],9,mat);s.ellipse((22,19,42,38),mat,3,'round',texture=True)
        board.paste(s.image,((i%7)*100+18,(i//7)*120+5),s.image)
        d.text(((i%7)*100+2,(i//7)*120+78),mat,fill=(224,222,209))
        for j,c in enumerate(MATERIALS[mat]):d.rectangle(((i%7)*100+6+j*14,(i//7)*120+98,(i%7)*100+18+j*14,(i//7)*120+109),fill=c)
    board.save(path)
