def _v4_now():
    return datetime.now(timezone.utc).isoformat()


def _v4_json(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)


def _v4_sha(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 128), b""):
            digest.update(block)
    return digest.hexdigest()


def _v4_atomic_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".pending")
    with temporary.open("w", encoding="utf-8") as handle:
        json.dump(value, handle, ensure_ascii=False, indent=2, sort_keys=True, allow_nan=False)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(str(temporary), str(path))


def _v4_atomic_png(path, image):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".pending")
    with temporary.open("wb") as handle:
        image.save(handle, format="PNG", optimize=False)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(str(temporary), str(path))


def technical_qa(image):
    """Inspect export integrity only. This never grants visual approval.

    Return {passed, errors, warnings, measurements}. Alpha and palette metrics
    are diagnostics; they cannot identify a hammer or judge its construction.
    """
    errors, warnings = [], []
    measurements = {"width": image.width, "height": image.height, "mode": image.mode}
    if image.size != (64, 64):
        errors.append("dimensions_must_be_64x64")
    if image.mode != "RGBA":
        errors.append("rgba_alpha_channel_required")
        return {"passed": False, "errors": errors, "warnings": warnings,
                "measurements": measurements}
    alpha = image.getchannel("A")
    histogram = alpha.histogram()
    visible = sum(histogram[1:])
    partial = sum(histogram[1:255])
    total = image.width * image.height
    bbox = alpha.getbbox()
    colors = image.getcolors(maxcolors=65537)
    color_count = len(colors) if colors is not None else 65538
    margin = min(bbox[0], bbox[1], image.width - bbox[2], image.height - bbox[3]) if bbox else 0
    measurements.update({"bbox": list(bbox) if bbox else None,
        "opaque_pixels": histogram[255], "visible_pixels": visible,
        "visible_fraction": round(visible / max(1, total), 6),
        "partial_alpha_fraction": round(partial / max(1, visible), 6),
        "color_count": color_count, "min_margin": margin})
    alpha.close()
    if not bbox or visible < max(32, total * 0.025):
        errors.append("empty_or_nearly_empty_silhouette")
    if bbox and max(bbox[2] - bbox[0], bbox[3] - bbox[1]) < 28:
        errors.append("subject_too_small_for_inventory_canvas")
    if visible > total * 0.88:
        errors.append("possible_opaque_background_contamination")
    if bbox and margin < 2:
        errors.append("clipped_object_or_insufficient_two_pixel_padding")
    if partial > visible * 0.35:
        errors.append("excessive_partial_alpha_edges")
    elif partial:
        warnings.append("partial_alpha_pixels_require_halo_review")
    if color_count > 512:
        errors.append("excessive_palette_count_over_512")
    elif color_count > 192:
        warnings.append("palette_count_over_192_requires_material_review")
    return {"passed": not errors, "errors": errors, "warnings": warnings,
            "measurements": measurements}


def _v4_fingerprints(recipe):
    recipe_fingerprint = hashlib.sha256(_v4_json(recipe).encode("utf-8")).hexdigest()
    render_fingerprint = hashlib.sha256(_v4_json({
        "recipe_fingerprint": recipe_fingerprint,
        "generator_version": GENERATOR_VERSION,
        "recipe_version": RECIPE_VERSION,
        "export_contract": "rgba64_inventory_v4.1"}).encode("utf-8")).hexdigest()
    return recipe_fingerprint, render_fingerprint


def _v4_slug(recipe):
    # Deliberately preserve familiar item/family paths. A UNIQUE constraint
    # rejects different logical IDs that would otherwise collide here.
    slug = recipe["id"].split(".")[-1]
    if not re.fullmatch(r"[a-z0-9_]+", slug):
        raise ValueError("Unsafe item filename component: " + slug)
    return slug


def _v4_relative_path(recipe, variant):
    root = Path("art") / "items" / recipe["family"] / _v4_slug(recipe)
    return (root / ("icon.png" if variant == 0 else
            "variants/icon_%05d.png" % variant)).as_posix()


def _v4_asset_id(recipe, variant):
    logical_id = recipe.get("canonical_item_id", recipe["id"])
    return logical_id + ".inventory." + recipe.get("state", "intact") + ".v%05d" % variant


def _v4_sidecar(path):
    return path.with_name("asset.json" if path.name == "icon.png" else path.stem + ".asset.json")


def _v4_is_approved(record):
    return bool(record.get("founder_approved")) or record.get("production_status") == "founder_approved" or record.get("qa_status") == "founder_approved"


def _v4_preserve_previous(base, destination, previous):
    """Preserve previous drafts as immutable evidence before a replacement."""
    if not destination.exists() or previous is None:
        return
    actual_digest = _v4_sha(destination)
    history = base / "history" / previous["asset_id"] / actual_digest
    history.mkdir(parents=True, exist_ok=True)
    archived = history / "icon.png"
    if not archived.exists():
        shutil.copyfile(str(destination), str(archived))
    metadata = history / "asset.json"
    if not metadata.exists():
        _v4_atomic_json(metadata, {"previous_record": previous,
            "archived_content_sha256": actual_digest,
            "previous_expected_sha256": previous.get("sha256"),
            "archived_at": _v4_now(),
            "reason": "versioned_draft_replacement_or_corruption_recovery"})


def _v4_assert_unapproved(path, previous):
    if previous and _v4_is_approved(previous):
        raise PermissionError("Approved master is immutable; use a versioned recipe/replacement: " + str(path))
    sidecar = _v4_sidecar(path)
    if sidecar.exists():
        try:
            value = json.loads(sidecar.read_text(encoding="utf-8"))
        except (ValueError, OSError) as error:
            raise ValueError("Unreadable existing asset metadata; refusing replacement: " + str(sidecar)) from error
        if _v4_is_approved(value):
            raise PermissionError("Founder-approved asset cannot be overwritten: " + str(path))


def _v4_check_or_repair_sidecar(base, destination, record):
    """Recover metadata from the committed checkpoint without editing pixels.

    Existing independent review fields are retained when identity/hash match.
    Corrupt or mismatched unapproved metadata is archived before replacement.
    A valid founder-approved record is never overwritten.
    """
    sidecar = _v4_sidecar(destination)
    if not sidecar.exists():
        _v4_atomic_json(sidecar, record)
        return True
    try:
        current = json.loads(sidecar.read_text(encoding="utf-8"))
        if not isinstance(current, dict):
            current = None
    except (OSError, ValueError, UnicodeError):
        current = None
    keys = ("asset_id", "logical_item_id", "sha256", "render_fingerprint")
    if current and all(current.get(key) == record.get(key) for key in keys):
        return False
    if current and _v4_is_approved(current):
        raise PermissionError("Approved asset metadata conflicts with the checkpoint; preserve it for review: " + str(sidecar))
    digest = _v4_sha(sidecar)
    history = base / "history" / record["asset_id"] / ("metadata_" + digest)
    history.mkdir(parents=True, exist_ok=True)
    preserved = history / "asset.json.original"
    if not preserved.exists():
        shutil.copyfile(str(sidecar), str(preserved))
    _v4_atomic_json(sidecar, record)
    return True


def _v4_database(base):
    connection = sqlite3.connect(str(base / "factory_state.sqlite3"))
    connection.row_factory = sqlite3.Row
    # A rollback journal is portable to iOS Files; do not depend on WAL sidecars.
    connection.execute("PRAGMA synchronous=FULL")
    connection.executescript("""
        CREATE TABLE IF NOT EXISTS jobs (
          asset_id TEXT PRIMARY KEY, logical_item_id TEXT NOT NULL,
          recipe_id TEXT NOT NULL, variant INTEGER NOT NULL,
          export_path TEXT NOT NULL UNIQUE, recipe_fingerprint TEXT NOT NULL,
          render_fingerprint TEXT NOT NULL, status TEXT NOT NULL,
          sha256 TEXT, record_json TEXT, error TEXT, updated_at TEXT NOT NULL);
        CREATE INDEX IF NOT EXISTS jobs_content_hash ON jobs(sha256);
        CREATE TABLE IF NOT EXISTS recipe_queue (
          position INTEGER PRIMARY KEY, recipe_id TEXT NOT NULL UNIQUE,
          logical_item_id TEXT NOT NULL UNIQUE, item_path TEXT NOT NULL UNIQUE,
          recipe_json TEXT NOT NULL, recipe_fingerprint TEXT NOT NULL,
          render_fingerprint TEXT NOT NULL);
    """)
    return connection


def _v4_stage_recipes(connection, recipes):
    """Validate the entire input before rendering. Disk indexes bound memory."""
    connection.execute("DELETE FROM recipe_queue")
    count = 0
    try:
        with connection:
            for index, raw in enumerate(recipes):
                try:
                    recipe = normalize_recipe(raw)
                    logical_id = recipe.get("canonical_item_id", recipe["id"])
                    if not re.fullmatch(r"[a-z0-9_]+(?:\.[a-z0-9_]+)*", logical_id):
                        raise ValueError("Invalid canonical logical item ID")
                    recipe_fp, render_fp = _v4_fingerprints(recipe)
                    path = str(Path(recipe["family"]) / _v4_slug(recipe))
                    connection.execute("INSERT INTO recipe_queue VALUES (?,?,?,?,?,?,?)",
                        (index, recipe["id"], logical_id, path, _v4_json(recipe), recipe_fp, render_fp))
                except sqlite3.IntegrityError as error:
                    raise ValueError("Duplicate logical/recipe ID or conflicting export path at recipe %d: %s" % (index + 1, raw.get("id", "unknown"))) from error
                except Exception as error:
                    raise ValueError("Invalid recipe %d: %s" % (index + 1, error)) from error
                count += 1
        return count
    except Exception:
        connection.rollback()
        raise


def _v4_selected_scope(connection, start, stop, variants):
    """Count persistent asset identities, including prior small invocations.

    The selected set is stored in SQLite rather than an output-sized Python
    list. Failed/pending identities remain registered so splitting a rejected
    calibration into many small calls cannot bypass the artistic review gate.
    """
    connection.execute("CREATE TEMP TABLE IF NOT EXISTS selected_assets (asset_id TEXT PRIMARY KEY, recipe_id TEXT NOT NULL, recipe_fingerprint TEXT NOT NULL)")
    connection.execute("DELETE FROM selected_assets")
    last_position, recipe, staged = None, None, None
    with connection:
        for job in range(start, stop):
            position, variant = divmod(job, variants)
            if position != last_position:
                staged = connection.execute("SELECT recipe_json,recipe_fingerprint FROM recipe_queue WHERE position=?", (position,)).fetchone()
                recipe = json.loads(staged["recipe_json"])
                last_position = position
            connection.execute("INSERT INTO selected_assets VALUES (?,?,?)",
                (_v4_asset_id(recipe, variant), recipe["id"], staged["recipe_fingerprint"]))
    existing = connection.execute("SELECT COUNT(*) FROM jobs").fetchone()[0]
    additional = connection.execute("SELECT COUNT(*) FROM selected_assets AS s LEFT JOIN jobs AS j ON s.asset_id=j.asset_id WHERE j.asset_id IS NULL").fetchone()[0]
    return existing + additional


def _v4_scaling_authorization(connection, requested, approval_path):
    if not approval_path:
        raise PermissionError("Artistic review gate: more than 24 outputs requires recorded founder scaling approval. Use --benchmark only for isolated synthetic engineering tests.")
    approval = json.loads(Path(approval_path).read_text(encoding="utf-8"))
    if (approval.get("scope") != "LAST_LIGHT_V4_SCALING" or
        not approval.get("approval_evidence") or not approval.get("founder") or
        approval.get("generator_version") != GENERATOR_VERSION or
        int(approval.get("max_outputs", 0)) < requested):
        raise PermissionError("Scaling approval lacks founder evidence, matching generator version, or sufficient output scope")
    approved = approval.get("approved_recipe_fingerprints", {})
    # Validate actual persistent identities plus the selected replacements,
    # rather than requiring approval for unrelated, unselected catalog rows.
    required = connection.execute("""SELECT recipe_id,recipe_fingerprint FROM jobs
        WHERE asset_id NOT IN (SELECT asset_id FROM selected_assets)
        UNION SELECT recipe_id,recipe_fingerprint FROM selected_assets""")
    for row in required:
        accepted = approved.get(row["recipe_id"])
        accepted = accepted if isinstance(accepted, list) else [accepted]
        if row["recipe_fingerprint"] not in accepted:
            raise PermissionError("Recipe is outside recorded scaling approval: " + row["recipe_id"])
    return approval


def _v4_output_mode(base, benchmark):
    marker = base / "factory_mode.json"
    desired = "synthetic_benchmark" if benchmark else "draft_art_production"
    if marker.exists():
        prior = json.loads(marker.read_text(encoding="utf-8"))
        if prior.get("mode") != desired:
            raise ValueError("Benchmark and production checkpoints require separate output folders: " + str(base))
    else:
        _v4_atomic_json(marker, {"mode": desired, "created_at": _v4_now(),
            "warning": "All new exports require visual review and founder approval. Benchmark variants are not independently designed objects."})


def _v4_render_job(recipe, variant):
    image = render_icon(recipe, variant=variant)
    try:
        qa = technical_qa(image)
        # Retain image ownership until main thread has atomically written it.
        return image, qa
    except Exception:
        image.close()
        raise


def _v4_record(recipe, variant, relative, recipe_fp, render_fp, digest, qa, benchmark):
    logical_id = recipe.get("canonical_item_id", recipe["id"])
    return {"asset_id": _v4_asset_id(recipe, variant), "logical_item_id": logical_id,
        "recipe_id": recipe["id"], "category": recipe.get("category", recipe["family"]),
        "family": recipe["family"], "archetype": recipe["archetype"],
        "variant": variant, "view": recipe.get("view", "inventory_icon"),
        "state": recipe.get("state", "intact"), "relative_path": relative,
        "width": 64, "height": 64, "size": [64, 64], "format": "RGBA_PNG",
        "anchor": None, "anchor_note": "Inventory icon; no world contact anchor is asserted.",
        "sha256": digest, "recipe_fingerprint": recipe_fp, "render_fingerprint": render_fp,
        "generator_version": GENERATOR_VERSION, "recipe_version": RECIPE_VERSION,
        "style_bible_version": "MASTER_SPRITE_BIBLE_V2",
        "source_reference_ids": recipe.get("source_reference_ids", []),
        "material_specification": recipe.get("parts", recipe.get("materials", recipe.get("material", ""))),
        "required_representations": ["inventory_icon"],
        "source_recipe": recipe,
        "technical_qa": qa, "qa_status": "technical_qa_passed" if qa["passed"] else "generated",
        "production_status": "visual_review_required", "founder_approved": False,
        "visual_qa": {"status": "not_reviewed", "scores": None, "reviewer": None},
        "godot_import_status": "not_tested", "device_verification_status": "not_tested",
        "provenance": {"authoring_method": "original_AI_assisted_native_pixel_template_with_procedural_variant_cleanup" if recipe.get("render_mode")=="authored_template" else "original_procedural_shape_grammar",
            "template_source_sha256": AUTHORED_TEMPLATE_SOURCE_SHA256 if recipe.get("render_mode")=="authored_template" else None,
            "native_template_sha256": recipe.get("template_sha256"),
            "external_reference_pixels_used": False, "generator": GENERATOR_VERSION,
            "recipe_version": RECIPE_VERSION, "source_artwork": "embedded_original_native64_template" if recipe.get("render_mode")=="authored_template" else "embedded_recipe_and_renderer",
            "seed": recipe.get("seed", 0), "variant": variant},
        "synthetic_benchmark": bool(benchmark), "created_at": _v4_now()}


def make_review_sheets(records, output_dir, name="review"):
    """Write five bounded, native/nearest-neighbor review sheets (max 24 items).

    records may contain `absolute_path`, `path`, or `relative_path` (with
    `base_dir`). Returns paths. These are review artifacts, never game assets.
    """
    records = list(records)
    if len(records) > V4_REVIEW_GROUP_SIZE:
        raise ValueError("Review groups are bounded to 24 icons; split larger batches")
    if not records:
        return []
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    outputs = []
    # All source pixel art remains unfiltered. 32/48 previews deliberately use
    # nearest sampling and must receive actual visual review for readability.
    layouts = [("native_64", 64, 1, (45, 48, 53)),
        ("pixel_3x", 64, 3, (45, 48, 53)),
        ("dark", 64, 2, (24, 27, 31)),
        ("light", 64, 2, (224, 222, 214)),
        ("readability_32", 32, 1, (45, 48, 53)),
        ("readability_48", 48, 1, (45, 48, 53))]
    cols = min(6, len(records))
    rows = int(math.ceil(len(records) / cols))
    for suffix, size, scale, background in layouts:
        cell_w = max(112, size * scale + 16)
        cell_h = size * scale + 30
        sheet = Image.new("RGB", (cols * cell_w, rows * cell_h), background)
        draw = ImageDraw.Draw(sheet)
        text_color = (45, 43, 39) if suffix == "light" else (224, 223, 211)
        for index, row in enumerate(records):
            path = row.get("absolute_path", row.get("path"))
            if path is None:
                path = Path(row.get("base_dir", ".")) / row["relative_path"]
            with Image.open(path) as original:
                icon = original.convert("RGBA")
            if size != 64 or scale != 1:
                resized = icon.resize((size * scale, size * scale), Image.Resampling.NEAREST)
                icon.close()
                icon = resized
            x = (index % cols) * cell_w + (cell_w - icon.width) // 2
            y = (index // cols) * cell_h + 2
            sheet.paste(icon, (x, y), icon)
            label = row.get("recipe_id", row.get("logical_item_id", row.get("id", "unknown"))).split(".")[-1]
            draw.text(((index % cols) * cell_w + 4, y + size * scale + 3),
                "%02d %s" % (index + 1, label[:17]), fill=text_color)
            icon.close()
        destination = output_dir / (name + "_" + suffix + ".png")
        _v4_atomic_png(destination, sheet)
        sheet.close()
        outputs.append(str(destination))
    return outputs


def _v4_archive(base, rows, destination):
    destination.parent.mkdir(parents=True, exist_ok=True)
    pending = destination.with_name(destination.name + ".pending")
    with zipfile.ZipFile(pending, "w", compression=zipfile.ZIP_DEFLATED,
                         compresslevel=3, allowZip64=True) as archive:
        with archive.open("manifest.jsonl", "w") as manifest:
            for row in rows:
                manifest.write((_v4_json(row) + "\n").encode("utf-8"))
        for row in rows:
            archive.write(base / row["relative_path"], arcname=row["relative_path"])
            sidecar = _v4_sidecar(base / row["relative_path"])
            if sidecar.exists():
                archive.write(sidecar, arcname=sidecar.relative_to(base).as_posix())
        archive.writestr("README.txt", "LAST LIGHT V4 ORIGINAL PROCEDURAL DRAFTS\nTechnical QA does not grant visual or founder approval.\nWorld, held, Godot, and iPhone execution are not asserted.\nSynthetic benchmark variants do not increase unique object counts.\n")
    with zipfile.ZipFile(pending) as archive:
        broken = archive.testzip()
        if broken:
            raise ValueError("ZIP CRC verification failed: " + broken)
        for row in rows:
            with archive.open(row["relative_path"]) as exported:
                digest = hashlib.sha256(exported.read()).hexdigest()
            if digest != row["sha256"]:
                raise ValueError("ZIP content hash mismatch: " + row["relative_path"])
    os.replace(str(pending), str(destination))
    return str(destination)


def _v4_snapshot(connection, base, start, stop, variants, chunk_size, benchmark):
    """Stream current committed records; memory never grows with output count."""
    run_name = "range_%09d_%09d" % (start, stop)
    manifest_path = base / "manifest.jsonl"
    pending = manifest_path.with_name(manifest_path.name + ".pending")
    error_path = base / "errors.jsonl"
    error_pending = error_path.with_name(error_path.name + ".pending")
    archives, reviews, archive_rows, review_rows = [], [], [], []
    png_files, passed, failed = 0, 0, 0
    selected_unique_count = connection.execute("SELECT COUNT(*) FROM recipe_queue WHERE position BETWEEN ? AND ?",
        (start // variants, max(start, stop - 1) // variants)).fetchone()[0] if stop > start else 0
    archetypes, unique_ids = set(), set()
    with pending.open("w", encoding="utf-8") as manifest, error_pending.open("w", encoding="utf-8") as errors:
        for job in range(start, stop):
            recipe_position, variant = divmod(job, variants)
            staged = connection.execute("SELECT recipe_json FROM recipe_queue WHERE position=?", (recipe_position,)).fetchone()
            if staged is None:
                continue
            recipe = json.loads(staged["recipe_json"])
            db_row = connection.execute("SELECT * FROM jobs WHERE asset_id=?", (_v4_asset_id(recipe, variant),)).fetchone()
            if db_row is None:
                continue
            if db_row["status"] == "failed":
                failed += 1
                errors.write(_v4_json({"job": job, "recipe_id": recipe["id"], "asset_id": db_row["asset_id"], "error": db_row["error"]}) + "\n")
                continue
            if db_row["status"] != "committed" or not db_row["record_json"]:
                continue
            record = json.loads(db_row["record_json"])
            if record["render_fingerprint"] != _v4_fingerprints(recipe)[1]:
                continue
            archetypes.add(recipe["archetype"])
            unique_ids.add(record["logical_item_id"])
            png_files += 1
            passed += int(record["technical_qa"]["passed"])
            manifest.write(_v4_json(record) + "\n")
            archive_rows.append(record)
            if not benchmark:
                review_rows.append(dict(record, absolute_path=str(base / record["relative_path"])))
                if len(review_rows) == V4_REVIEW_GROUP_SIZE:
                    reviews.extend(make_review_sheets(review_rows, base / "review_sheets", run_name + "_%04d" % (len(reviews) // 6 + 1)))
                    review_rows.clear()
            if len(archive_rows) >= chunk_size:
                archives.append(_v4_archive(base, archive_rows,
                    base / "zip_exports" / (run_name + "_part_%04d.zip" % (len(archives) + 1))))
                archive_rows.clear()
        if archive_rows:
            archives.append(_v4_archive(base, archive_rows,
                base / "zip_exports" / (run_name + "_part_%04d.zip" % (len(archives) + 1))))
        if review_rows:
            reviews.extend(make_review_sheets(review_rows, base / "review_sheets", run_name + "_%04d" % (len(reviews) // 6 + 1)))
        manifest.flush()
        errors.flush()
        os.fsync(manifest.fileno())
        os.fsync(errors.fileno())
    os.replace(str(pending), str(manifest_path))
    os.replace(str(error_pending), str(error_path))
    return {"manifest_path": str(manifest_path), "errors_path": str(error_path),
        "zip_paths": archives, "review_sheet_paths": reviews, "png_files": png_files,
        "technical_qa_passes": passed, "failed": failed,
        "unique_logical_objects": len(unique_ids), "selected_unique_logical_objects": selected_unique_count,
        "independently_designed_archetypes": len(archetypes)}


def run_batch(recipes, output_dir, variants=1, start=0, limit=24, workers=1,
              chunk_size=250, resume=True, benchmark=False, stop_after=None,
              approval_path=None):
    """Run a deterministic, resumable draft batch; output_dir is an isolated root.

    start/limit count output jobs, not logical items. limit=0 selects all jobs.
    stop_after simulates an interruption after N checked/committed jobs. A later
    identical call with resume=True verifies hashes and completes the remainder.
    More than 24 outputs requires a recipe-scoped founder authorization JSON,
    or benchmark=True in a separate folder. Benchmarks do not grant art approval.
    """
    if variants < 1 or start < 0 or limit < 0 or chunk_size < 1 or workers < 1:
        raise ValueError("variants/workers/chunk_size must be positive; start/limit nonnegative")
    if workers > 16:
        raise ValueError("Use at most 16 workers to bound queued image memory")
    if stop_after is not None and stop_after < 0:
        raise ValueError("stop_after must be nonnegative")
    base = Path(output_dir).expanduser().resolve()
    base.mkdir(parents=True, exist_ok=True)
    _v4_output_mode(base, benchmark)
    connection = _v4_database(base)
    started = time.perf_counter()
    stats = {"generated": 0, "resumed": 0, "rebuilt": 0, "failed": 0,
        "metadata_repaired": 0,
        "interrupted": False, "visual_qa_passes": 0, "founder_approvals": 0,
        "godot_integrations": 0, "device_verifications": 0,
        "synthetic_benchmark": bool(benchmark), "output_dir": str(base)}
    pending_futures = {}
    executor = None
    try:
        recipe_count = _v4_stage_recipes(connection, recipes)
        total = recipe_count * variants
        if total > V4_MAX_JOBS:
            raise ValueError("Job count exceeds configured 2,000,000 safety cap")
        stop = min(total, start + limit) if limit else total
        start = min(start, total)
        requested = max(0, stop - start)
        stats.update({"requested": requested, "recipe_count": recipe_count,
            "possible_outputs": total, "range_start": start, "range_stop": stop,
            "generated_variants": 0})
        if not benchmark:
            receipt = base / "scaling_authorization.json"
            authorization_path = approval_path or (str(receipt) if receipt.exists() else None)
            # Refuse an obviously oversized unauthorized selection immediately;
            # do not build a large queue just to discover the 24-output gate.
            if requested > 24 and not authorization_path:
                raise PermissionError("Artistic review gate: more than 24 outputs requires recorded founder scaling approval. Use --benchmark only for isolated synthetic engineering tests.")
            cumulative = _v4_selected_scope(connection, start, stop, variants)
            stats["cumulative_registered_asset_ids"] = cumulative
            if cumulative > 24:
                approval = _v4_scaling_authorization(connection, cumulative, authorization_path)
                _v4_atomic_json(receipt, approval)
                stats["scaling_authorization_path"] = str(receipt)
        print("LAST LIGHT V4 | %s | %d recipes | %d requested outputs | workers=%d" %
            ("SYNTHETIC BENCHMARK" if benchmark else "DRAFT / VISUAL REVIEW REQUIRED", recipe_count, requested, workers))
        print("Output:", base)
        executor = concurrent.futures.ThreadPoolExecutor(max_workers=workers)
        job_iterator = iter(range(start, stop))
        processed = 0
        exhausted = False
        # The DB and writes stay on one thread. At most 2*workers RGBA images
        # can be queued; contact/ZIP buffers have explicit independent bounds.
        while not exhausted or pending_futures:
            while not exhausted and len(pending_futures) < max(1, workers * 2):
                if stop_after is not None and processed + len(pending_futures) >= stop_after:
                    exhausted = True
                    stats["interrupted"] = processed + len(pending_futures) < requested
                    break
                try:
                    job = next(job_iterator)
                except StopIteration:
                    exhausted = True
                    break
                position, variant = divmod(job, variants)
                staged = connection.execute("SELECT * FROM recipe_queue WHERE position=?", (position,)).fetchone()
                recipe = json.loads(staged["recipe_json"])
                asset_id = _v4_asset_id(recipe, variant)
                relative = _v4_relative_path(recipe, variant)
                destination = base / relative
                previous_row = connection.execute("SELECT * FROM jobs WHERE asset_id=?", (asset_id,)).fetchone()
                previous_record = json.loads(previous_row["record_json"]) if previous_row and previous_row["record_json"] else None
                try:
                    if previous_row and previous_row["export_path"] != relative:
                        raise ValueError("Stable asset ID changed export path; use a versioned replacement")
                    can_resume = bool(resume and previous_row and previous_row["status"] == "committed"
                        and previous_row["render_fingerprint"] == staged["render_fingerprint"] and destination.exists())
                    if can_resume:
                        try:
                            with Image.open(destination) as check:
                                check.load()
                                check_qa = technical_qa(check)
                            can_resume = check_qa["passed"] and _v4_sha(destination) == previous_row["sha256"]
                        except (OSError, ValueError):
                            can_resume = False
                    if can_resume:
                        stats["metadata_repaired"] += int(_v4_check_or_repair_sidecar(base, destination, previous_record))
                        stats["resumed"] += 1
                        processed += 1
                        continue
                    _v4_assert_unapproved(destination, previous_record)
                    if destination.exists() and previous_row is None:
                        raise FileExistsError("Unmanaged existing image will not be overwritten: " + str(destination))
                    _v4_preserve_previous(base, destination, previous_record)
                    is_rebuild = bool(previous_row or destination.exists())
                    with connection:
                        connection.execute("""INSERT INTO jobs VALUES (?,?,?,?,?,?,?,?,?,?,?,?)
                            ON CONFLICT(asset_id) DO UPDATE SET
                            recipe_fingerprint=excluded.recipe_fingerprint,
                            render_fingerprint=excluded.render_fingerprint,
                            status='pending',error=NULL,updated_at=excluded.updated_at""",
                            (asset_id, recipe.get("canonical_item_id", recipe["id"]), recipe["id"], variant,
                             relative, staged["recipe_fingerprint"], staged["render_fingerprint"],
                             "pending", None, None, None, _v4_now()))
                    future = executor.submit(_v4_render_job, recipe, variant)
                    pending_futures[future] = (job, recipe, variant, relative,
                        staged["recipe_fingerprint"], staged["render_fingerprint"], is_rebuild)
                except (PermissionError, FileExistsError):
                    # Immutable/unmanaged output conflicts are authorization
                    # errors, not ordinary render failures to silently skip.
                    raise
                except Exception as error:
                    with connection:
                        connection.execute("UPDATE jobs SET status='failed',error=?,updated_at=? WHERE asset_id=?",
                            (str(error), _v4_now(), asset_id))
                    stats["failed"] += 1
                    processed += 1
                    print("FAILED", recipe["id"], type(error).__name__, str(error))
            if not pending_futures:
                continue
            done, _ = concurrent.futures.wait(pending_futures,
                return_when=concurrent.futures.FIRST_COMPLETED)
            for future in done:
                job, recipe, variant, relative, recipe_fp, render_fp, is_rebuild = pending_futures.pop(future)
                image = None
                asset_id = _v4_asset_id(recipe, variant)
                try:
                    image, qa = future.result()
                    if not qa["passed"]:
                        rejected = base / "rejected" / relative
                        _v4_atomic_png(rejected, image)
                        raise ValueError("Technical QA failed; candidate retained at %s: %s" % (rejected, ", ".join(qa["errors"])))
                    destination = base / relative
                    candidate = destination.with_name(destination.name + ".candidate")
                    _v4_atomic_png(candidate, image)
                    digest = _v4_sha(candidate)
                    duplicate = connection.execute("SELECT logical_item_id FROM jobs WHERE sha256=? AND logical_item_id<>? AND status='committed' LIMIT 1",
                        (digest, recipe.get("canonical_item_id", recipe["id"]))).fetchone()
                    if duplicate:
                        rejected = base / "rejected" / relative
                        rejected.parent.mkdir(parents=True, exist_ok=True)
                        os.replace(str(candidate), str(rejected))
                        raise ValueError("Identical PNG for different physical objects: " + duplicate["logical_item_id"])
                    os.replace(str(candidate), str(destination))
                    record = _v4_record(recipe, variant, relative, recipe_fp, render_fp, digest, qa, benchmark)
                    _v4_atomic_json(_v4_sidecar(destination), record)
                    with connection:
                        connection.execute("UPDATE jobs SET status='committed',sha256=?,record_json=?,error=NULL,updated_at=? WHERE asset_id=?",
                            (digest, _v4_json(record), _v4_now(), asset_id))
                    stats["generated"] += 1
                    stats["generated_variants"] += int(variant > 0)
                    stats["rebuilt"] += int(is_rebuild)
                except Exception as error:
                    with connection:
                        connection.execute("UPDATE jobs SET status='failed',error=?,updated_at=? WHERE asset_id=?",
                            (type(error).__name__ + ": " + str(error), _v4_now(), asset_id))
                    stats["failed"] += 1
                    print("FAILED", recipe["id"], type(error).__name__, str(error))
                finally:
                    if image is not None:
                        image.close()
                    processed += 1
                    if processed % 100 == 0 or processed == requested:
                        print("Progress %d/%d; generated=%d resumed=%d failed=%d" %
                            (processed, requested, stats["generated"], stats["resumed"], stats["failed"]))
        executor.shutdown(wait=True)
        executor = None
        snapshot = _v4_snapshot(connection, base, start, stop, variants, chunk_size, benchmark)
        snapshot["failed"] = max(snapshot["failed"], stats["failed"])
        stats.update(snapshot)
        stats["elapsed_seconds"] = round(time.perf_counter() - started, 6)
        stats["png_per_second"] = round(stats["generated"] / max(0.000001, stats["elapsed_seconds"]), 3)
        stats["generated_variant_png_files"] = sum(1 for row in connection.execute("SELECT variant FROM jobs WHERE status='committed'") if row["variant"] > 0)
        stats["manifest_sha256"] = _v4_sha(base / "manifest.jsonl")
        stats["benchmark_note"] = "Repeated recipes/condition seeds test engineering throughput only; they are not new independent objects." if benchmark else None
        _v4_atomic_json(base / "summary.json", stats)
        print("SUMMARY", _v4_json(stats))
        return stats
    finally:
        if executor is not None:
            executor.shutdown(wait=True)
            for future in pending_futures:
                if not future.cancelled() and future.exception() is None:
                    image, _ = future.result()
                    image.close()
        connection.close()


def discover_output_directory(explicit=""):
    """Choose a writable persistent app folder; never silently fall back to /tmp."""
    if explicit:
        choices = [Path(explicit).expanduser()]
    else:
        choices = []
        if V4_OUTPUT_FOLDER:
            choices.append(Path(V4_OUTPUT_FOLDER).expanduser())
        home = Path.home()
        choices.extend([home / "Documents" / WORK_FOLDER_NAME, home / WORK_FOLDER_NAME])
        try:
            choices.append(Path(__file__).resolve().parent / "LAST_LIGHT_FACTORY_V4")
        except NameError:
            pass
        choices.append(Path.cwd() / "LAST_LIGHT_FACTORY_V4")
    errors = []
    for choice in choices:
        try:
            choice.mkdir(parents=True, exist_ok=True)
            # Exclusive random creation cannot clobber an existing user's file.
            with tempfile.NamedTemporaryFile(prefix=".last_light_probe_", dir=str(choice), delete=True) as probe:
                probe.write(b"LAST LIGHT writable folder probe")
                probe.flush()
            return choice.resolve()
        except OSError as error:
            errors.append("%s: %s" % (choice, error))
    raise OSError("No writable persistent output folder. Set V4_OUTPUT_FOLDER to an accessible Documents/Files folder. " + "; ".join(errors))


def load_recipe_file(path):
    """Stream UTF-8 JSONL or a JSON array. JSONL scales without a large list."""
    path = Path(path)
    if path.suffix.lower() == ".json":
        with path.open(encoding="utf-8") as handle:
            rows = json.load(handle)
        if not isinstance(rows, list):
            raise ValueError("Recipe JSON must be an array of semantic object recipes")
        yield from rows
        return
    with path.open(encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, 1):
            if line.strip():
                try:
                    row = json.loads(line)
                except ValueError as error:
                    raise ValueError("%s line %d: %s" % (path, line_number, error)) from error
                if not isinstance(row, dict):
                    raise ValueError("Recipe line %d must be an object" % line_number)
                yield row


def main(argv=None):
    parser = argparse.ArgumentParser(description="LAST LIGHT V4 standalone original procedural draft sprite factory")
    parser.add_argument("--output", default="", help="Writable persistent output folder")
    parser.add_argument("--recipes", help="UTF-8 semantic recipe JSONL or JSON array (default: 24 embedded demos)")
    parser.add_argument("--variants", type=int, default=V4_VARIANTS)
    parser.add_argument("--start", type=int, default=V4_START_AT)
    parser.add_argument("--limit", type=int, default=V4_MAX_ITEMS, help="Output jobs; 0 means all; artistic gate still applies")
    parser.add_argument("--workers", type=int, default=V4_WORKERS)
    parser.add_argument("--chunk-size", type=int, default=V4_CHUNK_SIZE)
    parser.add_argument("--benchmark", action="store_true", help="Explicit isolated synthetic throughput test, never art approval")
    parser.add_argument("--stop-after", type=int, help="Controlled interruption after N processed jobs; resume with same parameters")
    parser.add_argument("--approval", help="Recorded founder scaling authorization JSON, not automatic visual approval")
    parser.add_argument("--no-resume", action="store_true")
    args = parser.parse_args(argv)
    output = discover_output_directory(args.output)
    if args.benchmark and not args.output:
        output = output / "synthetic_benchmarks"
    recipe_path = args.recipes or (str(output / 'recipes.jsonl') if not DEMO_MODE else '')
    if recipe_path and not Path(recipe_path).is_file():
        raise ValueError('Place your semantic recipes.jsonl in the printed output folder or set --recipes to an existing file')
    recipes = load_recipe_file(recipe_path) if recipe_path else demo_recipes()
    output.mkdir(parents=True, exist_ok=True)
    if not recipe_path:
        demo_path = output / "demo_recipes.jsonl"
        if not demo_path.exists():
            with demo_path.open("w", encoding="utf-8") as handle:
                for recipe in recipes:
                    handle.write(_v4_json(recipe) + "\n")
        print("Editable semantic recipes:", demo_path)
    print("Persistent folder:", output)
    print("Pillow version:", getattr(Image, "__version__", "unknown"))
    print("Device verification: not performed by this program. Save/export ZIPs through iOS Files as appropriate.")
    return run_batch(recipes, output, variants=args.variants, start=args.start,
        limit=args.limit, workers=args.workers, chunk_size=args.chunk_size,
        resume=V4_RESUME and not args.no_resume, benchmark=args.benchmark,
        stop_after=args.stop_after, approval_path=args.approval)


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print("FACTORY STOPPED:", type(error).__name__, str(error))
        raise
